import yaml, json, os, subprocess, httpx

with open('config.yaml') as f:
    cfg = yaml.safe_load(f)

print('=== COMPLETE HERMES SYSTEM AUDIT ===')
print()

all_errors = []
all_warnings = []
all_info = []

def err(msg):
    all_errors.append(msg)
    print(f'✗ {msg}')
def warn(msg):
    all_warnings.append(msg)
    print(f'⚠ {msg}')
def info(msg):
    all_info.append(msg)
    print(f'  ℹ {msg}')

# ── 1. PRIMARY MODEL ──
print('── PRIMARY MODEL ──')
m = cfg['model']
if not m.get('default'):
    err('primary model default खाली है')
else:
    info(f'primary: {m[\"default\"]}')
if not m.get('provider'):
    err('primary provider खाली है')
if not m.get('base_url'):
    err('primary base_url खाली है')
if m.get('api_mode') not in ['chat_completions', 'responses']:
    err(f'api_mode invalid: {m.get(\"api_mode\")}')
# Live check
try:
    r = httpx.get(m['base_url'] + '/models', timeout=10)
    if r.status_code == 200:
        info(f'primary API reachable: {r.status_code}')
    else:
        err(f'primary API status: {r.status_code}')
except Exception as e:
    err(f'primary API unreachable: {str(e)[:100]}')

# ── 2. FALLBACK ──
print()
print('── FALLBACK CHAIN ──')
bp = cfg.get('fallback_providers', [])
if not isinstance(bp, list):
    err(f'fallback_providers type wrong: {type(bp)}')
elif len(bp) == 0:
    err('fallback chain खाली है — primary fail होगा तो कुछ नहीं मिलेगा')
else:
    info(f'fallback entries: {len(bp)}')
    for i, e in enumerate(bp):
        if not e.get('provider'): err(f'fallback[{i}]: provider missing')
        if not e.get('model'): err(f'fallback[{i}]: model missing')
        if not e.get('base_url'): err(f'fallback[{i}]: base_url missing')
        if not e.get('trigger_on'): err(f'fallback[{i}]: trigger_on missing')
        if not e.get('max_retries') or e['max_retries'] < 1: err(f'fallback[{i}]: max_retries invalid')
        # Live Ollama check
        if e.get('base_url', '').startswith('http://localhost'):
            try:
                r = httpx.get(e['base_url'] + '/api/tags', timeout=5)
                if r.status_code == 200:
                    info(f'  fallback[{i}] Ollama OK: {len(json.loads(r.text).get(\"models\",[]))} models')
                else:
                    err(f'  fallback[{i}] Ollama: status {r.status_code}')
            except Exception as ex:
                err(f'  fallback[{i}] Ollama unreachable: {str(ex)[:80]}')

# ── 3. CUSTOM PROVIDERS ──
print()
print('── CUSTOM PROVIDERS ──')
for cp in cfg.get('custom_providers', []):
    if not cp.get('base_url'): err(f'{cp.get(\"name\",\"?\")}: base_url missing')
    if not cp.get('model'): err(f'{cp.get(\"name\",\"?\")}: model missing')
    if not cp.get('api_mode'): err(f'{cp.get(\"name\",\"?\")}: api_mode missing')
    elif cp['api_mode'] not in ['chat_completions', 'responses']:
        err(f'{cp.get(\"name\",\"?\")}: api_mode invalid')
    env_var = cp.get('key_env', '')
    env_val = os.environ.get(env_var, 'NOT SET')
    if not env_val or env_val == '':
        warn(f'{cp.get(\"name\",\"?\")}: {env_var} env var NOT SET')

# ── 4. BROWSER ──
print()
print('── BROWSER ──')
br = cfg.get('browser', {})
if br.get('backend') != 'browser-use':
    warn(f'browser.backend = {br.get(\"backend\")} (browser-use expected for Browser Use)')

if 'browser/browser-use' not in cfg['plugins']['enabled']:
    err('browser/browser-use plugin NOT enabled — browser tools will NOT work even if backend= browser-use')
else:
    info('browser/browser-use plugin enabled')

if not br.get('executable_path'):
    err('browser executable_path missing')
elif not os.path.exists(br['executable_path']):
    err(f'browser executable not found: {br[\"executable_path\"]}')
else:
    info(f'browser executable OK: {br[\"executable_path\"]}')

# browser_use Python package
try:
    import browser_use
    info('browser_use Python package: installed')
except ImportError:
    err('browser_use Python package NOT installed in venv')

# ── 5. COMPUTER USE ──
print()
print('── COMPUTER USE ──')
cu = cfg.get('computer_use', {})
if cu.get('backend') != 'cua-driver':
    warn(f'computer_use backend = {cu.get(\"backend\")} (cua-driver expected)')

if not cu.get('enabled'):
    err('computer_use NOT enabled')

# cua-driver binary
cua_bin = 'C:/Users/admin/AppData/Local/Programs/Cua/cua-driver/bin/cua-driver'
if not os.path.exists(cua_bin):
    err(f'cua-driver binary NOT found: {cua_bin}')
else:
    info(f'cua-driver binary OK: {os.path.getsize(cua_bin)} bytes')

# cua-driver daemon
try:
    r = subprocess.run([cua_bin, 'status'], capture_output=True, text=True, timeout=5)
    if r.returncode == 0:
        for line in r.stdout.split('\n'):
            if 'running' in line.lower() or 'pid' in line.lower():
                info(f'cua-driver: {line.strip()}')
        info('cua-driver daemon: running')
    else:
        err(f'cua-driver status: {r.stderr[:100]}')
except Exception as e:
    err(f'cua-driver status check failed: {e}')

# computer_use Python tool
try:
    sys_path = 'C:/Users/admin/AppData/Local/hermes/hermes-agent'
    import sys
    sys.path.insert(0, sys_path)
    from tools.computer_use_tool import handle_computer_use
    info('computer_use_tool module: loadable')
except Exception as e:
    err(f'computer_use_tool import failed: {str(e)[:100]}')

# ── 6. PLUGINS ──
print()
print('── PLUGINS ──')
enabled_set = set(cfg['plugins']['enabled'])
print(f'Enabled plugins: {len(enabled_set)}')
print(f'Disabled plugins: {159 - len(enabled_set)}')

# Must-have plugins
must_have = [
    ('browser/browser-use', 'Browser Use backend'),
    ('model-providers/custom', 'Custom provider support'),
    ('web/ddgs', 'Free web search'),
    ('security-guidance', 'Security warnings'),
]
for plugin, desc in must_have:
    if plugin in enabled_set:
        info(f'✓ {plugin}: {desc}')
    else:
        err(f'✗ {plugin}: {desc} — MISSING')

# Optional but useful
optional = [
    ('browser/browserbase', 'Browserbase cloud browser'),
    ('platforms/telegram', 'Telegram platform adapter'),
    ('platforms/whatsapp', 'WhatsApp platform adapter'),
    ('image_gen/openai', 'OpenAI image gen'),
    ('observability/langfuse', 'Langfuse tracing'),
]
for plugin, desc in optional:
    if plugin in enabled_set:
        info(f'✓ {plugin}: {desc} (optional)')
    else:
        warn(f'○ {plugin}: {desc} — not enabled (optional)')

# ── 7. TOOLSETS ──
print()
print('── TOOLSET COVERAGE ──')
for plat, tools in cfg['platform_toolsets'].items():
    essential = ['web', 'terminal', 'file', 'browser', 'computer_use', 'code_execution', 
                 'skills', 'memory', 'session_search', 'delegation', 'cronjob', 
                 'clarify', 'todo', 'vision', 'image_gen', 'tts']
    missing = [t for t in essential if t not in tools]
    if plat in ['cli', 'telegram']:
        if missing:
            err(f'{plat}: missing essential tools: {missing}')
        else:
            info(f'{plat}: all {len(essential)} essential tools present ({len(tools)} total)')
    else:
        info(f'{plat}: {len(tools)} tools ({len(missing)} essential missing — OK for non-primary platforms)')

# ── 8. PLATFORMS ──
print()
print('── PLATFORMS ──')
for name, pl in cfg.get('platforms', {}).items():
    if not pl.get('enabled'):
        warn(f'{name}: disabled')
        continue
    if name == 'telegram' and not pl.get('bot_token'):
        err(f'{name}: bot_token missing')
    else:
        info(f'{name}: enabled')

# WhatsApp status
try:
    with open('gateway_state.json') as f:
        gs = json.load(f)
    for pname, pstate in gs.get('platforms', {}).items():
        if pstate.get('state') == 'fatal':
            err(f'{pname}: FATAL — {pstate.get(\"error_message\", \"unknown\")}')
        elif pstate.get('state') == 'connected':
            info(f'{pname}: connected')
        elif pstate.get('needs_attention'):
            warn(f'{pname}: needs attention — {pstate.get(\"error_message\", \"\")}')
except Exception as e:
    err(f'gateway_state read failed: {e}')

# ── 9. MCP SERVERS ──
print()
print('── MCP SERVERS ──')
for name, mc in cfg.get('mcp_servers', {}).items():
    if not mc.get('enabled'):
        warn(f'{name}: disabled')
        continue
    if not mc.get('command'):
        err(f'{name}: command missing')
    else:
        info(f'{name}: enabled, command={mc[\"command\"]}')

# Check n8n connectivity
n8n_url = 'http://localhost:5678'
try:
    r = httpx.get(n8n_url, timeout=5)
    if r.status_code == 200:
        info(f'n8n: reachable at {n8n_url}')
    elif r.status_code == 401:
        info(f'n8n: reachable but auth required ({r.status_code})')
    else:
        warn(f'n8n: status {r.status_code}')
except Exception as e:
    warn(f'n8n: not reachable — {str(e)[:80]}')

# ── 10. SESSION RESET ──
print()
print('── SESSION RESET ──')
